Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "transform": [
    {"calculate": "datum[''Positive Rate''] * datum[''Total Reviews'']", "as": "pos_count"}
  ],
  "hconcat": [
    {
      "width": 190,
      "height": 130,
      "layer": [
        {
          "transform": [{"aggregate": [{"op": "count", "as": "n"}]}],
          "mark": {"type": "text", "align": "left", "baseline": "top", "x": 0, "y": 0, "fontSize": 11, "letterSpacing": 1.5, "color": "#8A7F6E", "text": "GUEST SATISFACTION"}
        },
        {
          "transform": [
            {"aggregate": [{"op": "sum", "field": "pos_count", "as": "p"}, {"op": "sum", "field": "Total Reviews", "as": "t"}]},
            {"calculate": "datum.p / datum.t", "as": "rate"}
          ],
          "mark": {"type": "text", "align": "left", "baseline": "top", "x": 0, "y": 22, "fontSize": 34, "fontWeight": 600, "color": "#14617E"},
          "encoding": {"text": {"field": "rate", "format": ".0%"}}
        },
        {
          "transform": [
            {"filter": "datum[''Total Reviews''] > 1000"},
            {"joinaggregate": [{"op": "max", "field": "Positive Rate", "as": "best"}]},
            {"filter": "datum[''Positive Rate''] == datum.best"},
            {"calculate": "''Best '' + datum.Year + '': '' + format(datum[''Positive Rate''], ''.0%'')", "as": "t"}
          ],
          "mark": {"type": "text", "align": "left", "baseline": "top", "x": 0, "y": 76, "fontSize": 12, "fontWeight": 600, "color": "#3E9A6A"},
          "encoding": {"text": {"field": "t"}}
        },
        {
          "transform": [
            {"filter": "datum[''Total Reviews''] > 1000"},
            {"joinaggregate": [{"op": "min", "field": "Positive Rate", "as": "low"}]},
            {"filter": "datum[''Positive Rate''] == datum.low"},
            {"calculate": "''Lowest '' + datum.Year + '': '' + format(datum[''Positive Rate''], ''.0%'')", "as": "t"}
          ],
          "mark": {"type": "text", "align": "left", "baseline": "top", "x": 0, "y": 96, "fontSize": 12, "color": "#6B6255"},
          "encoding": {"text": {"field": "t"}}
        }
      ]
    },
    {
      "width": 340,
      "height": 130,
      "transform": [{"filter": "datum[''Total Reviews''] > 1000"}],
      "encoding": {
        "x": {"field": "Year", "type": "ordinal", "axis": {"title": null, "labelAngle": 0, "domain": false, "ticks": false, "labelColor": "#8A7F6E", "labelFontSize": 10, "labelExpr": "\"''\" + substring(datum.label, 2)"}},
        "y": {"field": "Positive Rate", "type": "quantitative", "scale": {"zero": false}, "axis": null}
      },
      "layer": [
        {
          "mark": {
            "type": "area",
            "interpolate": "monotone",
            "color": {"x1": 0, "y1": 0, "x2": 0, "y2": 1, "gradient": "linear", "stops": [{"offset": 0, "color": "rgba(62,154,106,0.45)"}, {"offset": 1, "color": "rgba(62,154,106,0)"}]}
          }
        },
        {
          "mark": {
            "type": "line",
            "interpolate": "monotone",
            "strokeWidth": 3,
            "color": {"x1": 0, "y1": 0, "x2": 1, "y2": 0, "gradient": "linear", "stops": [{"offset": 0, "color": "#14617E"}, {"offset": 1, "color": "#3E9A6A"}]}
          }
        },
        {
          "transform": [
            {"window": [{"op": "rank", "as": "r"}], "sort": [{"field": "Year", "order": "descending"}]},
            {"filter": "datum.r == 1"}
          ],
          "mark": {"type": "point", "filled": true, "size": 70, "color": "#F2B632", "stroke": "#FFFFFF", "strokeWidth": 2}
        },
        {
          "mark": {"type": "point", "opacity": 0, "size": 200},
          "encoding": {
            "tooltip": [
              {"field": "Year"},
              {"field": "Positive Rate", "title": "Positive", "format": ".1%"},
              {"field": "Total Reviews", "title": "Reviews", "format": ","}
            ]
          }
        }
      ]
    }
  ],
  "spacing": 16,
  "config": {"view": {"stroke": null}, "font": "Segoe UI"}
}'
